import unicodedata

def display_width(text: str) -> int:
    width = 0
    for ch in text:
        cat = unicodedata.category(ch)
        if cat in ('Mn', 'Me', 'Cf'):
            continue  # zero-width
        eaw = unicodedata.east_asian_width(ch)
        if eaw in ('W', 'F'):
            width += 2
        else:
            width += 1
    return width
